[CmdletBinding()]
param([string]$ProjectRoot)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path};Import-Module (Join-Path $ProjectRoot 'ES/Automation/ABCD/ESABCInnovationRun.psm1') -Force
$fields=@('technicalInnovationLevel','safetyLevel','performanceLevel','reusabilityLevel','lifecycleLevel','networkLevel','debuggingLevel','editorProductionLevel','innovationDifferentialLevel','playerIncrementDelta');$a=[ordered]@{evidenceHash=('e'*64);providerId='provider-a'};$b=[ordered]@{evidenceHash=('e'*64);providerId='provider-b'};foreach($f in $fields){$a[$f]=3;$b[$f]=3};$stable=Compare-ESABCProviderEngineeringScores -EvaluationResults @([pscustomobject]$a,[pscustomobject]$b);$b['innovationDifferentialLevel']=4;$drift=Compare-ESABCProviderEngineeringScores -EvaluationResults @([pscustomobject]$a,[pscustomobject]$b);$b['evidenceHash']=('f'*64);$mismatch=Compare-ESABCProviderEngineeringScores -EvaluationResults @([pscustomobject]$a,[pscustomobject]$b);$pass=($stable.status -eq 'stable' -and $drift.status -eq 'drift-failed' -and $mismatch.status -eq 'drift-failed' -and @($mismatch.findings|Where-Object{$_ -like '*evidenceHash*'}).Count -gt 0);$state='failed';if($pass){$state='passed'};[pscustomobject]@{status=$state;stable=$stable.status;drift=$drift.status;evidenceMismatch=$mismatch.status;findingCount=@($mismatch.findings).Count};if(-not $pass){exit 1}
